	"    .irq_o(uart_irq_o_to_cpu_irq_i)\n"
	"  );\n"
	"  gpio #(\n"
	"    .DATA_W(16)\n"
	"  ) gpio (\n"
	"    .clk_i(clk_i),\n"
	"    .rst_ni(rst_ni),\n"
	"    .gpio_i(gpio_i),\n"
